import json
S = [3, 34, 7, 12, 5, 26, 11, 8, 15, 2, 19, 21]
T = 40
solutions = []

def backtrack(current, start):
    current_sum = sum(current)
    if current_sum == T:
        solutions.append(list(current))
        return
    if current_sum > T:
        return
    for i in range(start, len(S)):
        backtrack(current + [S[i]], i + 1)

backtrack([], 0)
# Verify each solution sums to T (redundant but per spec)
for sol in solutions:
    assert sum(sol) == T
witness = {
    "polarity": "positive",
    "data": {
        "solutions": solutions,
        "total_solutions": len(solutions)
    }
}
print("WITNESS: " + json.dumps(witness))
